function beginRitualMemory(){if(!game.ui.sessionStarted||game.screen!=='game'||game.phase!=='day'||game.story.ritualMemoryCompleted)return;const circle=window.village3D?.ritualSite?.();if(!circle||!window.village3D?.canWorkAt?.(circle)){notify('Подойди к обрядному кругу у левого края леса.','error');return}game.story.ritualApproached=true;game.ui.ritualCheckpoint={novelIndex:game.ui.novelIndex,novelChoice:game.ui.novelChoice,novelHistory:game.ui.novelHistory,textShown:game.ui.textShown,novelAuto:game.ui.novelAuto};game.ui.ritualMemoryActive=true;game.ui.novelIndex=game.ui.ritualMemoryIndex||0;game.ui.novelHistory=[];game.ui.textShown=0;game.ui.novelAuto=false;lastNovelBg='';go('novel')}
function finishRitualMemory(completed=true){if(!game.ui.ritualMemoryActive)return;if(completed){game.story.ritualMemoryCompleted=true;game.ui.ritualMemoryIndex=0;const note='У круга в Выселках я вспомнил обряд, увиденный молодым на службе. Культисты отравляли землю и собирались указать лесу ложного виновника. На нынешнем круге тот же знак и следы канавы. Это свидетельство их присутствия здесь; кто именно проводил местный обряд и когда — я ещё не знаю. Тень не подчинилась тем, кто её позвал. Разобрать знак можно, но это не вылечит землю.';if(!game.journal.includes(note))game.journal.push(note);recordStoryEvent('ritual-memory','ritual-cult.png','Круг и чёрная земля')}game.ui.ritualMemoryActive=false;if(game.ui.ritualCheckpoint)Object.assign(game.ui,game.ui.ritualCheckpoint);delete game.ui.ritualCheckpoint;lastNovelBg='';go('game');if(completed)notify('Воспоминание записано. Круг можно разобрать.','action')}
function ritualDiaryNotes(){return game.story.ritualMemoryCompleted?[{id:'ritual-memory',title:'Круг и чёрная земля',hint:'Воспоминание у лесной кромки',place:'Круг в Выселках',image:'ritual-cult.png',lead:'Молодым, на службе, я видел людей в тёмных капюшонах с красными знаками. Они выливали чужое в канаву, отравляли корни и собирались заставить лес обвинить другого. Призванная Тень не подчинилась им. У круга в моей деревне похожие следы. Значит, здесь действовали культисты — но время местного обряда ещё предстоит узнать.',aside:game.story.ritualDismantled?'Знак разобран. Порча земли остаётся.':'Круг можно разобрать. Это не очищает землю.',question:'Кто показал лесу ложного виновника?'}]:[]}
